def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited `coins`.
    If impossible, return -1. Classic unbounded knapsack / coin change DP.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array where dp[i] = min coins for amount i
    # Use amount+1 as infinity sentinel (since max coins needed is amount if coin 1 exists)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive coin values
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

def solve(meetings):
    # Greedy algorithm: sort by end time
    meetings = sorted(meetings, key=lambda x: x[1])
    count = 0
    current_end = -float('inf')
    for start, end in meetings:
        if start >= current_end:
            count += 1
            current_end = end
    return count

