def solve(lst):
    """Flatten a nested list (or tuple) of integers into a flat list preserving order.
    Only list or tuple objects are traversed; all other objects are treated as leaf values.
    """
    result = []
    def dfs(item):
        if isinstance(item, (list, tuple)):
            for sub in item:
                dfs(sub)
        else:
            result.append(item)
    dfs(lst)
    return result

