def solve(path: str) -> str:
    """Simplify a Unix-style absolute path.
    Resolve '.' and '..' components, collapse multiple slashes, and remove trailing slash.
    The result always starts with '/' and is '/' for the root.
    """
    # Guard against non-string inputs
    if not isinstance(path, str):
        return ''
    # Strip whitespace
    path = path.strip()
    # Split by '/', processing components
    parts = []
    for comp in path.split('/'):
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if parts:
                parts.pop()
        else:
            parts.append(comp)
    return '/' + '/'.join(parts) if parts else '/'
