def solve(grid):
    """Return the number of islands in a binary grid.
    An island is a group of horizontally or vertically adjacent cells containing 1.
    The input grid is not modified.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    count = 0
    for i in range(rows):
        cols = len(grid[i])
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) in visited:
                        continue
                    if x < 0 or x >= rows:
                        continue
                    if y < 0 or y >= len(grid[x]):
                        continue
                    if grid[x][y] != 1:
                        continue
                    visited.add((x, y))
                    stack.append((x + 1, y))
                    stack.append((x - 1, y))
                    stack.append((x, y + 1))
                    stack.append((x, y - 1))
    return count

