def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited
    coins from *coins*. Return -1 if impossible.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter positive unique coin values
    coins = [c for c in set(coins) if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                val = dp[i - c] + 1
                if val < best:
                    best = val
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

