    """
    if not isinstance(s, str):
        raise TypeError('Input must be a string')
    s = s.strip().upper()
    if not s:
        return 0
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for ch in reversed(s):
        val = values.get(ch)
        if val is None:
            # Unexpected character; according to spec this shouldn't happen
            raise ValueError(f'Invalid Roman numeral character: {ch}')
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

