def solve(a, b):
    # Levenshtein distance DP O(len(a)*len(b))
    m, n = len(a), len(b)
    # ensure the shorter string is second dimension to save memory? keep simple
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(m+1):
        dp[i][0] = i
    for j in range(n+1):
        dp[0][j] = j
    for i in range(1, m+1):
        ai = a[i-1]
        for j in range(1, n+1):
            if ai == b[j-1]:
                cost = 0
            else:
                cost = 1
            dp[i][j] = min(dp[i-1][j] + 1,      # deletion
                             dp[i][j-1] + 1,      # insertion
                             dp[i-1][j-1] + cost) # substitution
    return dp[m][n]

