def solve(s):
    """Convert a Roman numeral string to its integer value using standard subtractive rules.
    The input is guaranteed to be a valid Roman numeral consisting of the characters I,V,X,L,C,D,M.
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
