def solve(a, b):
    """Return the Levenshtein distance between strings a and b."""
    m, n = len(a), len(b)
    # Use O(min(m,n)) space by ensuring n <= m
    if n > m:
        a, b = b, a
        m, n = n, m
    previous = list(range(n + 1))  # distances for empty prefix of a
    for i in range(1, m + 1):
        current = [i] + [0] * n
        ai = a[i - 1]
        for j in range(1, n + 1):
            if ai == b[j - 1]:
                current[j] = previous[j - 1]
            else:
                current[j] = 1 + min(previous[j],      # deletion
                                      current[j - 1],   # insertion
                                      previous[j - 1])  # substitution
        previous = current
    return previous[n]

