def solve(grid):
    """Return the number of islands in a binary grid (0s and 1s).
    Cells are connected vertically and horizontally.
    Handles empty grid and empty rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows:
                    if 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1 and (ni, nj) not in visited:
                        stack.append((ni, nj))
    islands = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                islands += 1
                dfs(i, j)
    return islands

