def solve(a, x):
    """Return leftmost insertion index for x in sorted list a.
    Works for any sequence supporting __len__ and indexing.
    """
    # Ensure a is a sequence; if not, treat as empty
    try:
        n = len(a)
    except Exception:
        a = []
        n = 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        # Compare values, assuming elements are comparable with x
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def solve(lst):
    """Flatten a nested list of integers.
    Args:
        lst: list that may contain integers or other lists nested arbitrarily.
    Returns:
        A flat list of all integers in their original order.
    """
    result = []
    def dfs(item):
        if isinstance(item, list):
            for sub in item:
                dfs(sub)
        else:
            result.append(item)
    dfs(lst)
    return result

def solve(grid):
    """Count the number of islands in a 2D grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    Args:
        grid: List of lists of integers (0 or 1).
    Returns:
        Integer count of islands.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            i, j = stack.pop()
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj] == 1:
                    visited[ni][nj] = True
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                bfs(i, j)
    return count

